    ) : CdnApiError,
        DomainError,
        UploadAudioError,
        UploadAvatarError,
        UploadFileError,
        UploadImageError,
        UploadTypedImageError,
        UploadVideoError {
        override val remediation: Remediation
            get() = Remediation.ContactSupport
    }

    /**
     * This server cannot process {extension} images right now
     *
     * Code `error.503.image_decoder_unavailable`   status 503.
     *
     * @property envelope the server's answer.
     */
    public data class ImageDecoderUnavailable(
        override val envelope: ErrorEnvelope,
    ) : CdnApiError,
        DomainError,
        UploadAvatarError,
        UploadImageError,
        UploadTypedImageError {
        override val remediation: Remediation
            get() = Remediation.ContactSupport

        /**
         * Envelope param `extension`, when present.
         */
        public val extension: String?
            get() = envelope.params["extension"]
    }

    /**
     * Cannot verify workspace mandate right now
     *
     * Code `error.503.mandate_unavailable`   status 503.
     *
     * @property envelope the server's answer.
     */
    public data class MandateUnavailable(
        override val envelope: ErrorEnvelope,
    ) : CdnApiError,
        DomainError {
        override val remediation: Remediation
            get() = Remediation.Retry
    }

    /**
     * A code this client version does not know; its remediation is the backend's heuristic.
     *
     * @property envelope the server's answer.
     */
    public data class Unknown(
        override val envelope: ErrorEnvelope,
    ) : CdnApiError,
        DomainError,
        CdnImageOriginalError,
        CdnSignedMediaError,
        CheckFileExistsGetError,
        DescribeMediaError,
        RandomImageError,
        SyncRefsError,
        UploadAudioError,
        UploadAvatarError,
        UploadFileError,
        UploadImageError,
        UploadTypedImageError,
        UploadVideoError {
        override val remediation: Remediation
            get() = Remediation.default(envelope.code.value, envelope.status, envelope.params.names)
    }

    /**
     * A failure of the shared transport family (no response, session gone, step-up unresolved, throttled, server down, contract violated).
     *
     * @property failure the carried failure.
     */
    public data class Transport(
        override val failure: TransportFailure,
    ) : CdnApiError,
        TransportCarrier,
        CdnImageOriginalError,
        CdnSignedMediaError,
        CheckFileExistsGetError,
        DescribeMediaError,
        RandomImageError,
        SyncRefsError,
        UploadAudioError,
        UploadAvatarError,
        UploadFileError,
        UploadImageError,
        UploadTypedImageError,
        UploadVideoError

    /**
     * Envelope decoding.
     */
    public companion object {
        /**
         * The typed error for [envelope]; `Unknown` for a code outside the table.
         */
        public fun decode(envelope: ErrorEnvelope): CdnApiError = when (envelope.code.value) {
            "error.400.bad_request" -> BadRequest(envelope)
            "error.400.captcha_invalid" -> CaptchaInvalid(envelope)
            "error.400.captcha_required" -> CaptchaRequired(envelope)
            "error.400.expected_list" -> ExpectedList(envelope)
            "error.400.field.blank" -> FieldBlank(envelope)
            "error.400.field.does_not_exist" -> FieldDoesNotExist(envelope)
            "error.400.field.invalid" -> FieldInvalid(envelope)
            "error.400.field.invalid_choice" -> FieldInvalidChoice(envelope)
            "error.400.field.max_length" -> FieldMaxLength(envelope)
            "error.400.field.max_value" -> FieldMaxValue(envelope)
            "error.400.field.min_length" -> FieldMinLength(envelope)
            "error.400.field.min_value" -> FieldMinValue(envelope)
            "error.400.field.null" -> FieldNull(envelope)
            "error.400.field.required" -> FieldRequired(envelope)
            "error.400.field.unique" -> FieldUnique(envelope)
            "error.400.file_hash_required" -> FileHashRequired(envelope)
            "error.400.file_type_not_allowed" -> FileTypeNotAllowed(envelope)
            "error.400.image_type_required" -> ImageTypeRequired(envelope)
            "error.400.invalid_ad_id" -> InvalidAdId(envelope)
            "error.400.invalid_format" -> InvalidFormat(envelope)
            "error.400.invalid_hash" -> InvalidHash(envelope)
            "error.400.invalid_image_type" -> InvalidImageType(envelope)
            "error.400.missing_fields" -> MissingFields(envelope)
            "error.400.no_file" -> NoFile(envelope)
            "error.400.too_many_ids" -> TooManyIds(envelope)
            "error.400.too_many_refs" -> TooManyRefs(envelope)
            "error.400.validation_error" -> ValidationError(envelope)
            "error.400.verification_failed" -> VerificationFailed(envelope)
            "error.400.verification_invalid_factor" -> VerificationInvalidFactor(envelope)
            "error.401.unauthorized" -> Unauthorized(envelope)
            "error.402.payment_required" -> PaymentRequired(envelope)
            "error.403.forbidden" -> Forbidden(envelope)
            "error.403.network_blocked" -> NetworkBlocked(envelope)
            "error.403.storage_quota_exceeded" -> StorageQuotaExceeded(envelope)
            "error.403.verification_enrollment_required" -> VerificationEnrollmentRequired(envelope)
            "error.403.verification_required" -> VerificationRequired(envelope)
            "error.404.ad_not_found" -> AdNotFound(envelope)
            "error.404.media_not_found" -> MediaNotFound(envelope)
            "error.404.no_images" -> NoImages(envelope)
            "error.404.not_found" -> NotFound(envelope)
            "error.404.verification_challenge_not_found" -> VerificationChallengeNotFound(envelope)
            "error.405.method_not_allowed" -> MethodNotAllowed(envelope)
            "error.406.not_acceptable" -> NotAcceptable(envelope)
            "error.408.request_timeout" -> RequestTimeout(envelope)
            "error.409.conflict" -> Conflict(envelope)
            "error.410.gone" -> Gone(envelope)
            "error.413.file_too_large" -> FileTooLarge(envelope)
            "error.413.payload_too_large" -> PayloadTooLarge(envelope)
            "error.415.unsupported_media_type" -> UnsupportedMediaType(envelope)
            "error.422.unprocessable_entity" -> UnprocessableEntity(envelope)
            "error.423.locked" -> Locked(envelope)
            "error.423.verification_locked" -> VerificationLocked(envelope)
            "error.429.rate_limit" -> RateLimit(envelope)
            "error.429.too_many_requests" -> TooManyRequests(envelope)
            "error.500.internal" -> Internal(envelope)
            "error.503.image_decoder_unavailable" -> ImageDecoderUnavailable(envelope)
            "error.503.mandate_unavailable" -> MandateUnavailable(envelope)
